package org.sleepwell.app;
import java.util.*;import java.nio.ByteBuffer;import java.security.*;
/** Original bounded local similarity descriptor. No object/identity/liveness recognition. */
final class PictureSignature {
    final long hash;final int mean,contrast,gradient;final int[] histogram,edges;
    PictureSignature(long hash,int mean,int contrast,int gradient,int[] histogram,int[] edges){if((hash&1)!=0||mean<35||mean>230||contrast<18||contrast>128||gradient<10||gradient>255||histogram==null||histogram.length!=16||edges==null||edges.length!=64||Arrays.stream(histogram).anyMatch(n->n<0||n>1024)||Arrays.stream(histogram).sum()!=1024||Arrays.stream(edges).anyMatch(n->n<0||n>255))throw new IllegalArgumentException("Use a brighter, textured picture with visible detail.");this.hash=hash;this.mean=mean;this.contrast=contrast;this.gradient=gradient;this.histogram=histogram.clone();this.edges=edges.clone();}
    static PictureSignature from(byte[] pixels,int width,int height,int rotation){if(pixels==null||width<64||height<64||width>4096||height>4096||(long)width*height>4194304||pixels.length!=(long)width*height||rotation!=0&&rotation!=90&&rotation!=180&&rotation!=270)throw new IllegalArgumentException("Unsupported or incomplete picture frame.");int side=Math.min(width,height),left=(width-side)/2,top=(height-side)/2;double[] raw=new double[1024];for(int y=0;y<32;y++)for(int x=0;x<32;x++){int x0=left+x*side/32,x1=left+(x+1)*side/32,y0=top+y*side/32,y1=top+(y+1)*side/32,sum=0,count=0;for(int yy=y0;yy<y1;yy++)for(int xx=x0;xx<x1;xx++){sum+=pixels[yy*width+xx]&255;count++;}raw[y*32+x]=Math.round((double)sum/count);}int[] gray=new int[1024];for(int y=0;y<32;y++)for(int x=0;x<32;x++){int xx=rotation==90?31-y:rotation==180?31-x:rotation==270?y:x,yy=rotation==90?x:rotation==180?31-y:rotation==270?31-x:y;gray[yy*32+xx]=(int)raw[y*32+x];}double sum=0,squares=0,totalGradient=0;int comparisons=0;int[] histogram=new int[16],edges=new int[64],edgeCounts=new int[64];for(int y=0;y<32;y++)for(int x=0;x<32;x++){int value=gray[y*32+x];sum+=value;squares+=(double)value*value;histogram[value/16]++;int tile=y/4*8+x/4;if(x<31){int difference=Math.abs(value-gray[y*32+x+1]);edges[tile]+=difference;edgeCounts[tile]++;totalGradient+=difference;comparisons++;}if(y<31){int difference=Math.abs(value-gray[(y+1)*32+x]);edges[tile]+=difference;edgeCounts[tile]++;totalGradient+=difference;comparisons++;}}for(int n=0;n<64;n++)edges[n]=(int)Math.round((double)edges[n]/edgeCounts[n]);double average=sum/1024;int contrast=(int)Math.round(Math.sqrt(Math.max(0,squares/1024-average*average)));double[] coefficients=new double[64];for(int v=0;v<8;v++)for(int u=0;u<8;u++){double value=0;for(int y=0;y<32;y++)for(int x=0;x<32;x++)value+=gray[y*32+x]*COS[u][x]*COS[v][y];coefficients[v*8+u]=value;}double[] sorted=Arrays.copyOfRange(coefficients,1,64);Arrays.sort(sorted);double median=sorted[31];long hash=0;for(int n=1;n<64;n++)if(coefficients[n]>median)hash|=1L<<n;return new PictureSignature(hash,(int)Math.round(average),contrast,(int)Math.round(totalGradient/comparisons),histogram,edges);}
    private static final double[][] COS=cosines();private static double[][] cosines(){double[][] out=new double[8][32];for(int u=0;u<8;u++)for(int x=0;x<32;x++)out[u][x]=Math.cos((2*x+1)*u*Math.PI/64);return out;}
    boolean matches(PictureSignature other){if(other==null||Long.bitCount(hash^other.hash)>8||Math.abs(mean-other.mean)>25)return false;int histogramDifference=0,edgeDifference=0;for(int n=0;n<16;n++)histogramDifference+=Math.abs(histogram[n]-other.histogram[n]);for(int n=0;n<64;n++)edgeDifference+=Math.abs(edges[n]-other.edges[n]);return histogramDifference<=512&&edgeDifference<=64*18;}
    String key(){try{ByteBuffer bytes=ByteBuffer.allocate(340).putLong(hash).putInt(mean).putInt(contrast).putInt(gradient);for(int n:histogram)bytes.putInt(n);for(int n:edges)bytes.putInt(n);StringBuilder text=new StringBuilder();for(byte value:MessageDigest.getInstance("SHA-256").digest(bytes.array()))text.append(String.format(Locale.ROOT,"%02x",value&255));return text.toString();}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
}
